def moving_average(xs, k):
    if 1 <= k <= len(xs):
        window = []
        for i in range(len(xs)):
            if i >= k:
                window.pop(0)
            window.append(xs[i])
            if i >= k - 1:
                yield sum(window) / k
    else:
        raise ValueError("k must be between 1 and len(xs)")

